export const FIXTURE_NAMES = Object.freeze(Object.keys(PROJECTED_FIXTURES));

export function getProjectedFixture(name, viewer = 'public') {
  if (!Object.hasOwn(PROJECTED_FIXTURES, name) || !['public', 'host', 'tv', 'jon', 'lydia'].includes(viewer)) throw new RangeError('Unknown Gravity Orchard fixture/viewer.');
  return JSON.parse(JSON.stringify(PROJECTED_FIXTURES[name]));
}
